package synapse
import("context";"encoding/json";"fmt";"net/http";"net/url";"strconv";"time")
type userMediaPage struct{Media []struct{MediaLength int64 `json:"media_length"`;CreatedTS int64 `json:"created_ts"`} `json:"media"`;NextToken any `json:"next_token"`}
func(c *Client)WhoAmI(ctx context.Context,accessToken string)(string,error){req,err:=http.NewRequestWithContext(ctx,http.MethodGet,c.baseURL+"/_matrix/client/v3/account/whoami",nil);if err!=nil{return "",err};req.Header.Set("Authorization","Bearer "+accessToken);resp,err:=c.httpClient.Do(req);if err!=nil{return "",err};defer resp.Body.Close();var data struct{UserID string `json:"user_id"`};if resp.StatusCode<200||resp.StatusCode>=300{return "",fmt.Errorf("whoami HTTP %d",resp.StatusCode)};if err=json.NewDecoder(resp.Body).Decode(&data);err!=nil{return "",err};if data.UserID==""{return "",fmt.Errorf("whoami returned no user_id")};return data.UserID,nil}
func(c *Client)MediaBytesSince(ctx context.Context,userID string,since time.Time)(int64,error){var total int64;from:="";for page:=0;page<1000;page++{q:=url.Values{"limit":[]string{"100"}};if from!=""{q.Set("from",from)};_,raw,err:=c.AdminRequest(ctx,http.MethodGet,"/_synapse/admin/v1/users/"+url.PathEscape(userID)+"/media",q,nil);if err!=nil{return 0,err};var data userMediaPage;if err=json.Unmarshal(raw,&data);err!=nil{return 0,err};for _,item:=range data.Media{if item.CreatedTS>=since.UnixMilli(){total+=item.MediaLength}};if data.NextToken==nil{return total,nil};switch v:=data.NextToken.(type){case string:from=v;case float64:from=strconv.FormatInt(int64(v),10);default:return total,nil};if from==""{return total,nil}};return total,fmt.Errorf("media pagination exceeded safety limit")}
